content.query:
// Application exceptions by type and frequency
AppExceptions
| where TimeGenerated {timeRange}
| summarize ExceptionCount = count(), ImpactedUsers = dcount(UserId) by ExceptionType, ProblemId
| top 20 by ExceptionCount desc
| project ExceptionType, ProblemId, ExceptionCount, ImpactedUsers

// Exception trend over time
AppExceptions
| where TimeGenerated {timeRange}
| summarize ExceptionCount = count() by bin(TimeGenerated, 1h), ExceptionType
| order by TimeGenerated asc

// Dependency duration trend by type
AppDependencies
| where TimeGenerated {timeRange}
| summarize AvgDurationMs = avg(DurationMs) by bin(TimeGenerated, 1h), DependencyType
| order by TimeGenerated asc

// Custom event tracking – top events by volume
AppEvents
| where TimeGenerated {timeRange}
| summarize EventCount = count(), UniqueUsers = dcount(UserId) by Name
| top 20 by EventCount desc
| project EventName = Name, EventCount, UniqueUsers
